"use client";

import { AnimatePresence, motion } from "motion/react";
import { useEffect, useRef, useState } from "react";

export function DialogTailwind({ title = "Edit profile" }) {
  const [open, setOpen] = useState(false);
  const trigger = useRef<HTMLButtonElement>(null);
  const panel = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!open) return;
    panel.current?.querySelector("input")?.focus();
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false);
    document.addEventListener("keydown", onKey);
    return () => { document.removeEventListener("keydown", onKey); trigger.current?.focus(); };
  }, [open]);
  return (
    <>
      <button ref={trigger} type="button" onClick={() => setOpen(true)} className="h-9 rounded-lg border border-zinc-800 bg-zinc-900 px-4 text-sm font-medium text-zinc-100">Edit profile</button>
      <AnimatePresence>
        {open && (
          <div className="fixed inset-0 z-50 grid place-items-center p-4">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setOpen(false)} className="absolute inset-0 bg-black/50 backdrop-blur-sm" />
            <motion.div ref={panel} role="dialog" aria-modal="true" aria-labelledby="dlg-title" initial={{ opacity: 0, scale: 0.95, y: 8 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={{ opacity: 0, scale: 0.97 }} transition={{ duration: 0.22, ease: [0.16, 1, 0.3, 1] }} className="relative w-full max-w-md rounded-xl border border-zinc-800 bg-zinc-900 p-6 text-zinc-100 shadow-2xl">
              <h2 id="dlg-title" className="text-lg font-semibold">{title}</h2>
              <p className="mt-1 text-sm text-zinc-400">Make changes to your profile here.</p>
              <input aria-label="Name" defaultValue="Ada Lovelace" className="mt-5 h-9 w-full rounded-lg border border-zinc-800 bg-zinc-950 px-3 text-sm outline-none focus:border-indigo-500" />
              <div className="mt-6 flex justify-end gap-2">
                <button type="button" onClick={() => setOpen(false)} className="h-9 rounded-lg border border-zinc-800 px-4 text-sm">Cancel</button>
                <button type="button" onClick={() => setOpen(false)} className="h-9 rounded-lg bg-indigo-500 px-4 text-sm font-medium text-white">Save changes</button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </>
  );
}
